export function OnboardingChecklist({
  greeting = "{{greeting}}",
  accent = "{{accent}}",
  stepsDone = {{stepsDone}},
  tone = "{{tone}}",
  allDone = {{allDone}},
}) {
  const items = ["Create your workspace", "Invite a teammate", "Connect your data", "Take a quick tour"];
  const prefix = { friendly: "👋 ", minimal: "", celebratory: "✨ " }[tone] ?? "";
  const wrap = {
    friendly: {},
    minimal: { border: "1.5px dashed #24143035" },
    celebratory: { background: "linear-gradient(135deg, #FAF7F2, #F5C2E020)" },
  }[tone] ?? {};
  return (
    <div style={{ position: "relative", font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 22, maxWidth: 360, borderRadius: 16, border: "1.5px solid #24143018", ...wrap }}>
      <p style={{ margin: "0 0 4px", fontWeight: 700, fontSize: 16 }}>{prefix}{greeting}</p>
      <p style={{ margin: "0 0 14px", fontSize: 12.5, color: "#24143090" }}>{stepsDone} of 4 steps complete</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 10 }}>
        {items.map((label, i) => {
          const done = i < stepsDone;
          return (
            <li key={label} style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 14, opacity: done ? 1 : 0.55, fontWeight: done ? 600 : 400 }}>
              <span aria-hidden="true" style={{ width: 20, height: 20, borderRadius: 999, border: "1.5px solid " + (done ? accent : "#24143035"), background: done ? accent : "transparent", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11 }}>{done ? "✓" : ""}</span>
              {label}
            </li>
          );
        })}
      </ul>
      {allDone && (
        <p style={{ margin: "16px 0 0", padding: "10px 12px", borderRadius: 10, background: accent, fontSize: 13, fontWeight: 600, textAlign: "center" }}>You're all set — nice work!</p>
      )}
    </div>
  );
}
